            ]
          }
        }
      ],
      "rule": "weight - max(max_conflict_weight, conflict_weight - neighbor_edge_min)",
      "rationale": "Estimate competing feasible weight by subtracting edge deletion costs, with the strongest opponent as a floor."
    },
    {
